    est, rssd = R.align_vectors(a, b)
    assert closec(est.as_quat(), [-0.1273105070161581, -0.14692436072852136, -0.2717856198768211, 0.9425167605172738], 1e-10)
    assert closec([rssd], [0.02137784535620822], 1e-10)
    est, rssd, sens = R.align_vectors(a, b, return_sensitivity=True)
    assert closec(sens, [0.5014581163259381, -0.029888268658807556, 0.04187849838886929, -0.029888268658807556, 0.4642168053300947, 0.037112538734786836, 0.04187849838886929, 0.037112538734786836, 0.39754750812963346], 1e-10)
