    assert closec(est.as_quat(), [-0.12690749527901565, -0.14545198396735654, -0.26795765471008165, 0.9438945403403068], 1e-10)
    assert closec([rssd], [0.02578714138222902], 1e-10)
    est, rssd = R.align_vectors(a[0], b[1])
    assert closec(est.as_quat(), [0.0, 0.31519469569380304, -0.8002909414845235, 0.5100850054493917], 1e-10)
    assert closec([rssd], [0.00024948769303012597], 1e-10)
    est, rssd = R.align_vectors(a[0], -a[0])
    assert closec(est.as_quat(), [0.0, 0.0, -1.0, 6.123233995736766e-17], 1e-10)
    sl = Slerp(np.array([0.0, 1.0, 3.0, 4.5]), r)
